previewCss:
.darma-loader-darma-b12-teacup-steam { --accent: var(--loader-color, #f472b6); --accent-2: var(--loader-secondary-color, #a855f7); width: var(--loader-size, 96px); height: var(--loader-size, 96px); position: relative; }
.darma-loader-darma-b12-teacup-steam .darma-loader-darma-b12-teacup-steam__cup { position: absolute; bottom: 8%; left: 20%; width: 50%; height: 34%; background: linear-gradient(var(--accent), var(--accent-2)); border-radius: 6px 6px 42% 42%; }
.darma-loader-darma-b12-teacup-steam .darma-loader-darma-b12-teacup-steam__cup::after { content: ''; position: absolute; top: 14%; left: 92%; width: 30%; height: 52%; border: calc(var(--loader-size, 96px) * .045) solid var(--accent-2); border-left: 0; border-radius: 0 60% 60% 0; }
.darma-loader-darma-b12-teacup-steam::after { content: ''; position: absolute; bottom: 2%; left: 12%; width: 68%; height: 5%; border-radius: 999px; background: var(--accent-2); }
.darma-loader-darma-b12-teacup-steam span { position: absolute; bottom: 44%; width: 7%; height: 28%; border-radius: 999px; background: linear-gradient(transparent, color-mix(in srgb, #fff 62%, var(--accent-2))); animation: darma-loader-darma-b12-teacup-steam-steam calc(var(--loader-speed, 1s) * 2.2) ease-in-out infinite; }
.darma-loader-darma-b12-teacup-steam span:nth-child(1) { left: 26%; animation-delay: 0s; }
.darma-loader-darma-b12-teacup-steam span:nth-child(2) { left: 41%; animation-delay: calc(var(--loader-speed, 1s) * .55); }
.darma-loader-darma-b12-teacup-steam span:nth-child(3) { left: 56%; animation-delay: calc(var(--loader-speed, 1s) * 1.1); }
@keyframes darma-loader-darma-b12-teacup-steam-steam { 0% { opacity: 0; transform: translateY(24%) scaleY(.5); } 35% { opacity: .9; } 100% { opacity: 0; transform: translateY(-86%) scaleY(1.25); } }

